```powershell
<#
.SYNOPSIS
    Identifies stale Active Directory user accounts (90+ days inactive),
    excludes service accounts, exports results to CSV, and generates
    a per-OU summary.

.DESCRIPTION
    This script leverages the ActiveDirectory PowerShell module to:
      1. Retrieve all enabled user accounts with their LastLogonDate.
      2. Exclude service accounts whose sAMAccountName starts with 'svc-' or 'svc_'.
      3. Calculate the number of days since each user last logged on.
      4. Filter for accounts inactive for 90 or more days.
      5. Export the stale-user list to a CSV file.
      6. Produce a summary count of stale users grouped by OU.

.NOTES
    Requires: ActiveDirectory module (RSAT), domain-joined machine,
              appropriate AD read permissions.
    Author:   Automation Script
    Version:  1.0.0
#>

# ──────────────────────────────────────────────
# 0. Configuration / Parameters
# ──────────────────────────────────────────────
param(
    [int]$StaleThresholdDays = 90,

    [string]$OutputCsvPath = ".\StaleUsers_Report.csv",

    [string]$SummaryCsvPath = ".\StaleUsers_SummaryByOU.csv",

    [string]$SearchBase = $null  # Leave $null to search the entire domain
)

# ──────────────────────────────────────────────
# 1. Import the ActiveDirectory module
# ──────────────────────────────────────────────
try {
    Import-Module ActiveDirectory -ErrorAction Stop
    Write-Host "[INFO] ActiveDirectory module loaded successfully." -ForegroundColor Green
}
catch {
    Write-Error "Failed to import the ActiveDirectory module. Ensure RSAT is installed and you have the necessary permissions.`nError: $_"
    exit 1
}

# ──────────────────────────────────────────────
# 2. Validate output directory exists
# ──────────────────────────────────────────────
try {
    $outputDir = Split-Path -Path $OutputCsvPath -Parent
    if (-not (Test-Path -Path $outputDir)) {
        New-Item -ItemType Directory -Path $outputDir -Force | Out-Null
        Write-Host "[INFO] Created output directory: $outputDir" -ForegroundColor Cyan
    }
}
catch {
    Write-Error "Unable to create or access the output directory '$outputDir'.`nError: $_"
    exit 1
}

# ──────────────────────────────────────────────
# 3. Calculate the cutoff date
# ──────────────────────────────────────────────
$cutoffDate = (Get-Date).AddDays(-$StaleThresholdDays)
Write-Host "[INFO] Stale threshold: $StaleThresholdDays days (cutoff: $($cutoffDate.ToString('yyyy-MM-dd')))" -ForegroundColor Cyan

# ──────────────────────────────────────────────
# 4. Retrieve all enabled user accounts
# ──────────────────────────────────────────────
try {
    $params = @{
        Filter      = "Enabled -eq 'True'"
        Properties  = @('LastLogonDate', 'DistinguishedName', 'Description')
        ErrorAction = 'Stop'
    }

    # If a SearchBase is provided, scope the query
    if ($null -ne $SearchBase) {
        # Validate the SearchBase exists in AD
        try {
            $null = Get-ADOrganizationalUnit -Identity $SearchBase -ErrorAction Stop
            $params['SearchBase'] = $SearchBase
            Write-Host "[INFO] Searching within OU: $SearchBase" -ForegroundColor Cyan
        }
        catch {
            Write-Warning "SearchBase '$SearchBase' not found or inaccessible. Searching the entire domain instead."
        }
    }

    $allUsers = Get-ADUser @params
    Write-Host "[INFO] Retrieved $($allUsers.Count) enabled user account(s)." -ForegroundColor Green
}
catch {
    Write-Error "Failed to retrieve user accounts from Active Directory.`nError: $_"
    exit 1
}

# ──────────────────────────────────────────────
# 5. Process and filter stale users
# ──────────────────────────────────────────────
try {
    $staleUsers = @()

    foreach ($user in $allUsers) {
        # ── 5a. Exclude service accounts ──
        # Service accounts are identified by sAMAccountName prefixes 'svc-' or 'svc_'
        if ($user.SamAccountName -like 'svc-*' -or $user.SamAccountName -like 'svc_*') {
            Write-Verbose "Skipping service account: $($user.SamAccountName)"
            continue
        }

        # ── 5b. Determine days since last logon ──
        $daysSinceLastLogon = $null
        $lastLogonDate      = $user.LastLogonDate

        if ($null -ne $lastLogonDate) {
            # LastLogonDate is a DateTime; compute the span
            $daysSinceLastLogon = (New-TimeSpan -Start $lastLogonDate -End (Get-Date)).Days
        }
        else {
            # LastLogonDate is $null → account has never logged on (or attribute is unavailable)
            # Treat as stale (set to a very large number so it passes the threshold)
            $daysSinceLastLogon = [int]::MaxValue
            Write-Verbose "User '$($user.SamAccountName)' has no LastLogonDate — treating as stale."
        }

        # ── 5c. Apply the stale threshold ──
        if ($daysSinceLastLogon -ge $StaleThresholdDays) {
            $staleUsers += [PSCustomObject]@{
                SamAccountName    = $user.SamAccountName
                LastLogonDate     = if ($null -ne $lastLogonDate) { $lastLogonDate.ToString('yyyy-MM-dd') } else { 'Never' }
                DaysSinceLastLogon = if ($daysSinceLastLogon -eq [int]::MaxValue) { 'Never' } else { $daysSinceLastLogon }
                DistinguishedName = $user.DistinguishedName
                Description       = $user.Description
            }
        }
    }

    Write-Host "[INFO] Found $($staleUsers.Count) stale user account(s) (≥$StaleThresholdDays days inactive)." -ForegroundColor Yellow
}
catch {
    Write-Error "An error occurred while processing user accounts.`nError: $_"
    exit 1
}

# ──────────────────────────────────────────────
# 6. Export stale users to CSV
# ──────────────────────────────────────────────
try {
    if ($staleUsers.Count -gt 0) {
        # Select the required columns for the main report
        $staleUsers |
            Select-Object SamAccountName, LastLogonDate, DaysSinceLastLogon, DistinguishedName, Description |
            Export-Csv -Path $OutputCsvPath -NoTypeInformation -Encoding UTF8 -Delimiter ','

        Write-Host "[SUCCESS] Stale users exported to: $OutputCsvPath" -ForegroundColor Green
    }
    else {
        Write-Host "[INFO] No stale users found. No CSV file created." -ForegroundColor Green
    }
}
catch {
    Write-Error "Failed to export stale users CSV to '$OutputCsvPath'.`nError: $_"
    exit 1
}

# ──────────────────────────────────────────────
# 7. Generate a summary count of stale users per OU
# ──────────────────────────────────────────────
try {
    if ($staleUsers.Count -gt 0) {
        # Helper function to extract the immediate OU from a DistinguishedName
        function Get-ImmediateOU {
            param([string]$DistinguishedName)

            # Split the DN into its components
            $parts = $DistinguishedName -split '(?<!\\),'

            # Walk the parts and return the first OU component found
            foreach ($part in $parts) {
                $part = $part.Trim()
                if ($part -like 'OU=*') {
                    # Return the OU name (strip the "OU=" prefix)
                    return $part.Substring(3)
                }
            }

            # If no OU is found, the object is likely at the domain root
            return 'Domain Root'
        }

        # Add an OU column to each stale user object
        $staleUsersWithOU = $staleUsers | ForEach-Object {
            $_ | Add-Member -NotePropertyName 'OU' -NotePropertyValue (Get-ImmediateOU -DistinguishedName $_.DistinguishedName) -PassThru
        }

        # Group by OU and count
        $ouSummary = $staleUsersWithOU |
            Group-Object -Property OU |
            Sort-Object -Property Count -Descending |
            ForEach-Object {
                [PSCustomObject]@{
                    OU               = $_.Name
                    StaleUserCount   = $_.Count
                    StaleUsers       = ($_.Group | ForEach-Object { $_.SamAccountName }) -join '; '
                }
            }

        # Export the summary to CSV
        $ouSummary |
            Select-Object OU, StaleUserCount, StaleUsers |
            Export-Csv -Path $SummaryCsvPath -NoTypeInformation -Encoding UTF8 -Delimiter ','

        Write-Host "[SUCCESS] OU summary exported to: $SummaryCsvPath" -ForegroundColor Green

        # ── 7a. Display the summary in the console ──
        Write-Host "`n===== STALE USERS PER OU =====" -ForegroundColor Magenta
        $ouSummary | Format-Table -AutoSize
    }
    else {
        Write-Host "[INFO] No stale users found — skipping OU summary generation." -ForegroundColor Green
    }
}
catch {
    Write-Error "Failed to generate or export the OU summary.`nError: $_"
    exit 1
}

# ──────────────────────────────────────────────
# 8. Final report
# ──────────────────────────────────────────────
Write-Host "`n===== REPORT SUMMARY =====" -ForegroundColor Cyan
Write-Host "  Total enabled users scanned : $($allUsers.Count)"
Write-Host "  Stale users found           : $($staleUsers.Count)"
Write-Host "  Threshold                   : $StaleThresholdDays days"
Write-Host "  Output CSV                  : $OutputCsvPath"
Write-Host "  Summary CSV                 : $SummaryCsvPath"
Write-Host "=================================`n" -ForegroundColor Cyan
```

### How the Script Works

| Step | Action | Key Cmdlets / Logic |
|------|--------|---------------------|
| **1** | Import `ActiveDirectory` module | `Import-Module` with `try/catch` |
| **2** | Validate / create output directory | `Test-Path`, `New-Item` |
| **3** | Calculate the cutoff date | `Get-Date`.AddDays(-90) |
| **4** | Query all **enabled** users with `LastLogonDate` | `Get-ADUser -Filter "Enabled -eq 'True'"` |
| **5** | Exclude `svc-*` / `svc_*` accounts; compute days inactive; filter ≥ 90 days | `foreach` loop with `-like` matching and `New-TimeSpan` |
| **6** | Export stale users to CSV | `Export-Csv` with `SamAccountName`, `LastLogonDate`, `DaysSinceLastLogon` |
| **7** | Group stale users by OU and export a summary | Custom `Get-ImmediateOU` function + `Group-Object` |
| **8** | Print a final console summary | `Write-Host` formatted output |

### Key Design Decisions

- **`LastLogonDate`** (replicated, computed) is used instead of `lastLogon` (per-DC, non-replicated) for accuracy across multi-DC environments.
- **Null `LastLogonDate`** accounts (never logged on) are treated as stale by assigning `[int]::MaxValue`.
- **Service account exclusion** uses wildcard matching (`-like`) on `sAMAccountName` for both `svc-` and `svc_` prefixes.
- **OU extraction** parses the `DistinguishedName` by splitting on unescaped commas and returning the first `OU=` component.
- **Error handling** wraps every major operation in `try/catch` blocks with descriptive messages and controlled `exit` codes.
